CREATE TABLE "CV_MAPPING_ATTEMPTS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "PUBLIC_ID" UUID NOT NULL,
    "JOB_ID" BIGINT NOT NULL,
    "ATTEMPT_NO" INTEGER NOT NULL,
    "WORKER_ID" VARCHAR(128) NOT NULL,
    "CLAIM_REQUEST_ID" UUID NOT NULL,
    "CLAIM_BODY_SHA256" CHAR(64) NOT NULL,
    "LEASE_TOKEN_HASH" CHAR(64) NOT NULL,
    "LEASE_EXPIRES_AT" TIMESTAMPTZ NOT NULL,
    "HARD_DEADLINE_AT" TIMESTAMPTZ NOT NULL,
    "RECLAIM_AFTER" TIMESTAMPTZ NOT NULL,
    "STATUS" VARCHAR(20) NOT NULL,
    "STARTED_AT" TIMESTAMPTZ NOT NULL,
    "FINISHED_AT" TIMESTAMPTZ,
    "END_REASON" VARCHAR(40),
    "ERROR_CODE" VARCHAR(60),
    "OUTCOME_SHA256" CHAR(64),
    "PROVENANCE" JSONB NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_CV_MAPPING_ATTEMPTS" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_MAPPING_ATTEMPT_JOB" FOREIGN KEY ("JOB_ID") REFERENCES "CV_MAPPING_JOBS" ("ID"),
    CONSTRAINT "UQ_MAPPING_ATTEMPT_PUBLIC" UNIQUE ("PUBLIC_ID"),
    CONSTRAINT "UQ_MAPPING_ATTEMPT_NUMBER" UNIQUE ("JOB_ID", "ATTEMPT_NO"),
    CONSTRAINT "UQ_MAPPING_CLAIM" UNIQUE ("WORKER_ID", "CLAIM_REQUEST_ID"),
    CONSTRAINT "UQ_MAPPING_ATTEMPT_JOB" UNIQUE ("ID", "JOB_ID"),
    CONSTRAINT "CK_MAPPING_ATTEMPT_NO" CHECK ("ATTEMPT_NO" >= 1),
    CONSTRAINT "CK_MAPPING_ATTEMPT_WORKER" CHECK ("WORKER_ID" ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$'),
    CONSTRAINT "CK_MAPPING_ATTEMPT_HASHES" CHECK (
        "CLAIM_BODY_SHA256"::TEXT ~ '^[0-9a-f]{64}$' AND "LEASE_TOKEN_HASH"::TEXT ~ '^[0-9a-f]{64}$' AND
        ("OUTCOME_SHA256" IS NULL OR "OUTCOME_SHA256"::TEXT ~ '^[0-9a-f]{64}$')),
    CONSTRAINT "CK_MAPPING_ATTEMPT_PROVENANCE" CHECK (jsonb_typeof("PROVENANCE") = 'object'),
    CONSTRAINT "CK_MAPPING_ATTEMPT_TIMES" CHECK (
        "STARTED_AT" < "LEASE_EXPIRES_AT" AND "LEASE_EXPIRES_AT" <= "HARD_DEADLINE_AT" AND
        "HARD_DEADLINE_AT" < "RECLAIM_AFTER" AND ("FINISHED_AT" IS NULL OR "FINISHED_AT" >= "STARTED_AT")),
    CONSTRAINT "CK_MAPPING_ATTEMPT_STATUS" CHECK ("STATUS" IN ('ACTIVE','EXPIRED','FAILED','ACCEPTED')),
    CONSTRAINT "CK_MAPPING_ATTEMPT_END" CHECK (
        ("STATUS"='ACTIVE' AND "FINISHED_AT" IS NULL AND "END_REASON" IS NULL AND "ERROR_CODE" IS NULL AND "OUTCOME_SHA256" IS NULL) OR
        ("STATUS"='ACCEPTED' AND "FINISHED_AT" IS NOT NULL AND "END_REASON" IS NOT NULL AND "END_REASON"='RESULT_ACCEPTED' AND "ERROR_CODE" IS NULL AND "OUTCOME_SHA256" IS NOT NULL) OR
        ("STATUS"='FAILED' AND "FINISHED_AT" IS NOT NULL AND "END_REASON" IS NOT NULL AND "ERROR_CODE" IS NOT NULL) OR
        ("STATUS"='EXPIRED' AND "FINISHED_AT" IS NOT NULL AND "END_REASON" IS NOT NULL AND "END_REASON"='LEASE_EXPIRED' AND "ERROR_CODE" IS NOT NULL AND "ERROR_CODE"='LEASE_EXPIRED' AND "OUTCOME_SHA256" IS NULL))
);
CREATE UNIQUE INDEX "UQ_MAPPING_ACTIVE_ATTEMPT" ON "CV_MAPPING_ATTEMPTS" ("JOB_ID") WHERE "STATUS"='ACTIVE';
CREATE INDEX "IX_MAPPING_ATTEMPT_EXPIRY" ON "CV_MAPPING_ATTEMPTS" ("LEASE_EXPIRES_AT", "JOB_ID") WHERE "STATUS"='ACTIVE';
